class InvariantViolationError(Exception):
    """Raised when payload invariant validation fails."""
    pass


def validate_invariant(payload: any) -> bool:
    """
    Validates the invariant of the given payload.
    Raises InvariantViolationError if the payload is invalid or violates security constraints.
    Returns True if validation succeeds.
    """
    if payload is None:
        raise InvariantViolationError("Payload cannot be None.")

    if isinstance(payload, (str, bytes)) and len(payload) == 0:
        raise InvariantViolationError("Payload cannot be empty.")

    if isinstance(payload, dict) and not payload.get('valid', True):
        raise InvariantViolationError("Payload invariant check failed.")

    return True


